import { StyleFn } from "..";

export const Footer: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const { asset } = theme;

  return {
    root: {
      display: "flex",
      flexDirection: "column",
      padding: `0 ${size.spacing[16]}`,
      fontSize: font.size.small,
      backgroundColor: color.surface.accent.corporate[mode],
      color: color.text.white[mode],
      // FIXME workaround for secondary and extended bottom borders
      // not displaying in white color in footer light mode
      "&:not([data-theme='dark'])": {
        "& $secondary:after, & $extended": {
          borderColor: color.border.neutral.white["light"],
        },
      }
    },
    primary: {
      width: "100%",
      display: "flex",
      alignItems: "center",
      padding: `${size.spacing[16]} 0`,
    },
    secondary: {
      position: "relative",
      display: "flex",
      margin: `0 -${size.spacing[16]}`,
      padding: `${size.spacing[16]} ${size.spacing[24]}`,
      backgroundRepeat: "no-repeat",
      backgroundPositionX: "center",
      backgroundPositionY: size.spacing[16],
      fontSize: font.size.medium,
      "&:after": {
        position: "absolute",
        content: "''",
        bottom: 0,
        left: "1rem",
        right: "1rem",
        height: 1,
        borderBottom: `1px solid ${color.border.neutral.white[mode]}`,
      },
      "& .ds-text--h6, & h6": {
        color: "white",
      },
    },
    extended: {
      color: color.text.white[mode],
      display: "flex",
      paddingTop: size.spacing[16],
      paddingBottom: size.spacing[8],
      borderBottom: `1px solid ${color.border.neutral.white[mode]}`,
    },
    primaryLinks: {
      flex: 1,
    },
    copyright: {},
    logo: {
      marginLeft: size.spacing[32],
      backgroundImage: `url('data:image/svg+xml;base64,${asset.image.logo.value}')`,
      backgroundRepeat: "no-repeat",
      width: asset.image.logo.width,
      height: asset.image.logo.height,
    },
    // responsive variant for small screens
    _mobile: {
      "& $primary": {
        flexDirection: "column",
        justifyContent: "center",
        padding: size.spacing[24],
        gap: size.spacing[24],
      },
      
      "& $primaryLinks": {
        // Mobile variant: keep primary links centered horizontally.
        // We use a full-width container so `justifyContent: center` can
        // center the links row (and any wrapped lines) within the footer.
        flex: "unset",
        width: "100%",
        justifyContent: "center",
        alignItems: "center",
        textAlign: "center",
      },
      "& $secondary": {
        flexDirection: "column",
        padding: size.spacing[24],
      },
      "& $logo": {
        order: -1,
        marginLeft: 0,
      },
    },
  };
};
